static void vin_u_parse_vin_sym (Parse_Context * const parse_context , Vin_Sym * const vin_sym)
{
  if (!vin_c_parse_vin_sym (parse_context , vin_sym))
    {
      vin_throw_exception  (parse_context , VIN_ERR_SYNTAX) ;
    }
}

